// Entry of the Next server Worker (wrangler.app.jsonc).
//
// Only the routing Worker (cloudflare/worker.ts, through cloudflare/front-handler.ts)
// calls it, over a service binding, with requests the routing layer already
// resolved and could not answer from the cache. It has no public URL: those
// requests carry internal routing headers that must not be accepted from the
// internet.

import "./sentry-safe-random-id";
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { runWithCloudflareRequestContext } from "../.open-next/cloudflare/init.js";

type Context = { waitUntil(promise: Promise<unknown>): void };
type ServerHandler = (
  request: Request,
  env: unknown,
  ctx: Context,
  signal: AbortSignal
) => Promise<Response>;

export default {
  async fetch(request: Request, env: unknown, ctx: Context): Promise<Response> {
    return runWithCloudflareRequestContext(request, env, ctx, async () => {
      // Imported inside the request, as OpenNext's own worker does: the module
      // starts the Next server with a top-level await (instrumentation, Sentry),
      // and a Worker's global scope allows no I/O or timers.
      // @ts-expect-error -- generated by `opennextjs-cloudflare build`
      const { handler }: { handler: ServerHandler } = await import(
        "../.open-next/server-functions/default/handler.mjs"
      );
      return handler(request, env, ctx, request.signal);
    });
  },
};
